import { Suspense } from 'react'
import { RevenueChart } from './RevenueChart'
import { LatestInvoices } from './LatestInvoices'
import { CardStats } from './CardStats'
import {
  ChartSkeleton,
  InvoicesSkeleton,
  StatsSkeleton,
} from './DashboardSkeletons'

type DashboardData = {
  totalRevenue: number
  totalInvoices: number
  revenue: { month: string; amount: number }[]
  invoices: { id: string; name: string; amount: number }[]
}

function getDashboardData(): Promise<DashboardData> {
  // Keep the live dashboard data request out of the prerendered shell.
  return fetch('https://api.example.com/dashboard').then(async (res) => {
    if (!res.ok) {
      throw new Error('Failed to load dashboard data')
    }

    return (await res.json()) as DashboardData
  })
}

async function DashboardStats({
  data,
}: {
  data: Promise<DashboardData>
}) {
  const { totalRevenue, totalInvoices } = await data

  return (
    <CardStats
      totalRevenue={totalRevenue}
      totalInvoices={totalInvoices}
    />
  )
}

async function DashboardRevenue({ data }: { data: Promise<DashboardData> }) {
  const { revenue } = await data
  return <RevenueChart revenue={revenue} />
}

async function DashboardInvoices({ data }: { data: Promise<DashboardData> }) {
  const { invoices } = await data
  return <LatestInvoices invoices={invoices} />
}

export default function Page() {
  const dashboardData = getDashboardData()

  return (
    <main className="dashboard-shell">
      <header className="dashboard-header">
        <p className="eyebrow">Business overview</p>
        <h1>Dashboard</h1>
        <p className="dashboard-description">
          Track revenue and keep an eye on recent invoices.
        </p>
      </header>

      <section className="dashboard-section" aria-label="Summary metrics">
        <Suspense fallback={<StatsSkeleton />}>
          <DashboardStats data={dashboardData} />
        </Suspense>
      </section>

      <section className="dashboard-grid" aria-label="Revenue and invoices">
        <Suspense fallback={<ChartSkeleton />}>
          <DashboardRevenue data={dashboardData} />
        </Suspense>
        <Suspense fallback={<InvoicesSkeleton />}>
          <DashboardInvoices data={dashboardData} />
        </Suspense>
      </section>
    </main>
  )
}
function Placeholder({ className = '' }: { className?: string }) {
  return <span className={`skeleton ${className}`} aria-hidden="true" />
}

export function StatsSkeleton() {
  return (
    <div className="stats-grid" aria-busy="true">
      <article className="card stat-card">
        <h2>Total Revenue</h2>
        <Placeholder className="stat-placeholder" />
      </article>
      <article className="card stat-card">
        <h2>Total Invoices</h2>
        <Placeholder className="stat-placeholder short" />
      </article>
    </div>
  )
}

export function ChartSkeleton() {
  return (
    <section className="panel chart" aria-busy="true">
      <h2>Revenue</h2>
      <ul className="skeleton-list" aria-hidden="true">
        {[0, 1, 2, 3, 4].map((item) => (
          <li key={item}>
            <Placeholder className="row-placeholder" />
          </li>
        ))}
      </ul>
    </section>
  )
}

export function InvoicesSkeleton() {
  return (
    <section className="panel invoices" aria-busy="true">
      <h2>Latest Invoices</h2>
      <ul className="skeleton-list" aria-hidden="true">
